// recipe: sound-play-probe
// args: none
// returns: ok, armed, played, count, entries, error, detail
//
// Decides whether the recorded-sound instrument is LIVE on `Sound.Play`: it arms the recorder, calls the game's own string
// overload once by reflection (a fresh call site, compiled after the patch was installed), and reads the buffer back. If the
// buffer holds the probe clip the patch is live and the game's own callers are the reason a fixture records nothing (an
// inlined call site); if the buffer stays empty the patch never reaches the method at all.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); var recorder = (System.Type)null; var sound = (System.Type)null; for (var i = 0; i < assemblies.Length; i++) { if (recorder == null) { try { recorder = assemblies[i].GetType("CasualtiesUnknownOnline.Acceptance.SoundPlayRecorder", false); } catch { recorder = null; } } if (sound == null) { try { sound = assemblies[i].GetType("Sound", false); } catch { sound = null; } } } if (recorder == null || sound == null) { return "{\"ok\":false,\"error\":\"type-missing\"}"; } recorder.GetMethod("Start", flags).Invoke(null, null); var play = sound.GetMethod("Play", flags, null, new System.Type[] { typeof(string), typeof(UnityEngine.Vector2), typeof(bool), typeof(bool), typeof(UnityEngine.Transform), typeof(float), typeof(float), typeof(bool), typeof(bool) }, null); if (play == null) { return "{\"ok\":false,\"error\":\"no-play-overload\"}"; } var played = "threw"; try { play.Invoke(null, new object[] { "probe", UnityEngine.Vector2.zero, false, true, null, 1f, 1f, false, false }); played = "ok"; } catch (System.Exception exception) { played = exception.GetType().Name; } var since = recorder.GetMethod("Since", flags).Invoke(null, new object[] { "probe" }); var count = 0; var builder = new System.Text.StringBuilder(); var list = since as System.Collections.IEnumerable; if (list != null) { foreach (var entry in list) { var type = entry.GetType(); builder.Append(type.GetProperty("Clip").GetValue(entry, null) as string).Append(';'); count++; } } return "{\"ok\":true,\"armed\":true,\"played\":\"" + played + "\",\"count\":" + count.ToString(System.Globalization.CultureInfo.InvariantCulture) + ",\"entries\":\"" + builder.ToString() + "\"}"; }))()
